from __future__ import annotations

import base64
import hashlib


# Compact, deterministic no-false-negative filter over the 1,659 semantic task
# identities materialized by the retired Stage 4 v1 exploratory attempts.  The
# source set digest makes the provenance auditable without shipping old data.
RETIRED_V1_SEMANTIC_COUNT = 1659
RETIRED_V1_SEMANTIC_SET_SHA256 = (
    "88905a683979f8dfef646a2ae48610ce388fdb100abbb186ce9315a7734565f2"
)
RETIRED_V1_BLOOM_BITS = 32768
RETIRED_V1_BLOOM_HASHES = 4
RETIRED_V1_BLOOM_SHA256 = (
    "127853d09d3326c8156c5b3577728faea2592ec4f47ba2525f3cb92c2f141f54"
)
_RETIRED_V1_BLOOM_BASE64 = (
    ""
)
_RETIRED_V1_BLOOM = base64.b64decode(_RETIRED_V1_BLOOM_BASE64)

if len(_RETIRED_V1_BLOOM) * 8 != RETIRED_V1_BLOOM_BITS:
    raise RuntimeError("Retired Stage 4 v1 Bloom filter has the wrong size")
if hashlib.sha256(_RETIRED_V1_BLOOM).hexdigest() != RETIRED_V1_BLOOM_SHA256:
    raise RuntimeError("Retired Stage 4 v1 Bloom filter checksum mismatch")


def retired_v1_semantic_maybe_contains(semantic_sha256: str) -> bool:
    """Return true for every retired v1 task, with only harmless false positives."""

    if len(semantic_sha256) != 64:
        raise ValueError("Semantic identity must be a SHA-256 hex digest")
    value = bytes.fromhex(semantic_sha256)
    for index in range(RETIRED_V1_BLOOM_HASHES):
        digest = hashlib.sha256(
            b"stage4-retired-v1|" + bytes([index]) + value
        ).digest()
        bit = int.from_bytes(digest[:8], "big") % RETIRED_V1_BLOOM_BITS
        if not (_RETIRED_V1_BLOOM[bit // 8] & (1 << (bit % 8))):
            return False
    return True
